//! 🌱️ A typed original registration owns its exact erased Window owner through private insertion, publication or cancellation.
use super::*;
use semio_framework_job::{StepContext,OriginalSourceBinding,OriginalTurnFailure,OriginalConstructionDemand,admit_original_construction,close_original_retained_step};
use std::{marker::PhantomData,mem::{ManuallyDrop,size_of,size_of_val}};
/// 🎟️ Per-instance Window registration retains the same caller, registry lifetime and typed owner until handoff.
pub struct OriginalWindowOwnerRegistration<O:WindowConfigOwner>{binding:OriginalSourceBinding,lifetime:u64,key:Option<&'static str>,owner:ManuallyDrop<Option<Box<dyn ErasedWindowConfigStoreOwner>>>,inserting:bool,adopted:bool,closing:bool,marker:PhantomData<fn()->O>}
fn admission(d:RetirementDemand)->OriginalConstructionDemand{OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth}}
fn invalid(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,message)}
impl WindowConfigOwnerRegistry{
 /// 🌱️ The caller admits an empty typed frontier before any actual owner or registry page is born.
 pub fn admit_original_owner<O:WindowConfigOwner>(&self,cx:&mut StepContext<'_>,output:&mut Option<Box<OriginalWindowOwnerRegistration<O>>>)->Result<bool,OriginalTurnFailure>{if output.is_some()||O::WINDOW_KIND_ID.is_empty()||O::SCHEMA.is_empty()||self.owners.contains_key(O::WINDOW_KIND_ID){return Err(invalid("original Window registration requires its unique typed identity and empty destination").into())}let d=RetirementDemand{copy_bytes:2*size_of::<OriginalWindowOwnerRegistration<O>>(),capacity_bytes:size_of::<OriginalWindowOwnerRegistration<O>>(),depth:1,..Default::default()};let binding=OriginalSourceBinding::borrow(cx);admit_original_construction(cx,output,admission(d),|_|Ok((Box::new(OriginalWindowOwnerRegistration{binding,lifetime:self.lifetime,key:Some(O::WINDOW_KIND_ID),owner:ManuallyDrop::new(None),inserting:false,adopted:false,closing:false,marker:PhantomData}),RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,..Default::default()})))?;Ok(output.is_some())}
}
impl<O:WindowConfigOwner> OriginalWindowOwnerRegistration<O>{
 pub fn owner_birth_demands()->RetirementDemand{RetirementDemand{copy_bytes:2*size_of::<TypedWindowConfigStoreOwner<O>>()+2*size_of::<Box<dyn ErasedWindowConfigStoreOwner>>()+size_of::<protocol::ActorId>(),capacity_bytes:size_of::<TypedWindowConfigStoreOwner<O>>(),depth:2,..Default::default()}}
 fn validate(&self,registry:&WindowConfigOwnerRegistry,cx:&StepContext<'_>)->Result<(),ValueError>{if !self.binding.matches(cx)||self.lifetime!=registry.lifetime{return Err(invalid("original Window registration changed its caller or per-instance registry"))}Ok(())}
 /// 📬️ The exact owner is invisible until its private insertion publishes the final original row.
 pub fn step(&mut self,registry:&mut WindowConfigOwnerRegistry,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(registry,cx)?;if self.adopted{return Ok(true)}if self.closing{return Err(invalid("original Window registration is closing").into())}if self.owner.is_none(){let d=Self::owner_birth_demands();admit_original_construction(cx,&mut self.owner,admission(d),|_|Ok((Box::new(TypedWindowConfigStoreOwner::<O>::new(registry.local_actor_id().clone()))as Box<dyn ErasedWindowConfigStoreOwner>,RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,..Default::default()})))?;return Ok(false)}let mut d=registry.owners.insert_original_demands()?;d.copy_bytes=d.copy_bytes.checked_add(3*size_of::<bool>()).ok_or_else(||invalid("Window registration publication header overflow"))?;let grant=cx.retained_grant();let mut done=None;admit_original_construction(cx,&mut done,admission(d),|_|{let(ready,mut p)=registry.owners.insert_original(&mut self.key,&mut self.owner,RetainedCloneGrant{maximum_copy_bytes:grant.maximum_copy_bytes-3*size_of::<bool>(),..grant})?;self.inserting=!ready;self.adopted=ready;self.closing=ready;p.copied_bytes+=3*size_of::<bool>();Ok((ready,p))})?;Ok(self.adopted)}
 /// ♻️ Cancellation first restores the private insertion hole, then closes the same actual owner and physical box.
 pub fn close_step(&mut self,registry:&mut WindowConfigOwnerRegistry,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(registry,cx)?;cx.with_original_retirement(|cx|{if !self.closing{let d=RetirementDemand{copy_bytes:size_of::<bool>(),depth:1,..Default::default()};close_original_retained_step(cx,d,|_|{self.closing=true;Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))})?;return Ok(false)}if self.inserting{let mut d=registry.owners.cancel_insert_original_demands()?;d.copy_bytes+=size_of::<bool>();close_original_retained_step(cx,d,|grant|{let(ready,mut p)=registry.owners.cancel_insert_original(&mut self.key,&mut self.owner,RetainedCloneGrant{maximum_copy_bytes:grant.maximum_copy_bytes-size_of::<bool>(),..grant})?;self.inserting=!ready;p.copied_bytes+=size_of::<bool>();Ok(RetainedCloneStep::Progress(p))})?;return Ok(false)}if let Some(owner)=self.owner.as_ref(){if owner.terminal_is_empty(){let d=RetirementDemand{copy_bytes:size_of::<Option<Box<dyn ErasedWindowConfigStoreOwner>>>(),release_bytes:size_of_val(&**owner),depth:1,..Default::default()};close_original_retained_step(cx,d,|_|{self.owner.take();Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()}))})?;return Ok(false)}let before=cx.retained_progress();let grant=cx.retained_grant();let step=self.owner.as_mut().unwrap().close_step_context(grant,cx).map_err(OriginalTurnFailure::from)?;let p=semio_framework_plugin_ownership::bounded_ownership::original_lifecycle_unposted(step.progress().unwrap_or_default(),before,cx.retained_progress())?;cx.consume_retained(p)?;cx.consume_fuel(p.copied_items as u64);return Ok(false)}Ok(self.terminal_is_empty())})}
 pub fn terminal_is_empty(&self)->bool{self.closing&&!self.inserting&&self.owner.is_none()}
 pub fn boxed_release_demands()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<Option<Box<Self>>>(),release_bytes:size_of::<Self>(),depth:1,..Default::default()}}
}
impl<O:WindowConfigOwner> Drop for OriginalWindowOwnerRegistration<O>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original Window registration retains its exact owner and private insertion until original closure")}}
